from __future__ import annotations

import ast
import re
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]


def replace_function(text:str,name:str,new_src:str)->str:
    tree=ast.parse(text)
    node=next((n for n in tree.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name==name),None)
    if node is None: raise RuntimeError(f'missing function {name}')
    lines=text.splitlines(keepends=True)
    return ''.join(lines[:node.lineno-1])+new_src.rstrip()+"\n\n"+''.join(lines[node.end_lineno:])

